struct Node {
    int data;
    unique_ptr<Node> left;
    unique_ptr<Node> right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

class BST {
private:
    unique_ptr<Node> root;

    unique_ptr<Node> sortedArrayToBST(const vector<int>& arr, int start, int end) {
        if (start > end) return nullptr;
        int mid = start + (end - start) / 2;  // Safe midpoint
        auto node = make_unique<Node>(arr[mid]);
        node->left = sortedArrayToBST(arr, start, mid - 1);
        node->right = sortedArrayToBST(arr, mid + 1, end);
        return node;
    }

public:
    BST() = default;

    bool buildFromSorted(const vector<int>& sortedArr) {
        if (sortedArr.empty()) return true;
        try {
            root = sortedArrayToBST(sortedArr, 0, sortedArr.size() - 1);
            return true;
        } catch (...) {
            return false;
        }
    }

    vector<int> inorderTraversal() const {
        vector<int> result;
        const auto traverse = [&](const auto& self, const unique_ptr<Node>& node) {
            if (!node) return;
            self(self, node->left);
            result.push_back(node->data);
            self(self, node->right);
        };
        traverse(traverse, root);
        return result;
    }
};

pair<vector<int>, bool> selectionSort(vector<int> arr) {
    if (arr.empty()) return {arr, true};
    if (is_sorted(arr.begin(), arr.end())) return {arr, true};  // Early exit

    for (size_t i = 0; i < arr.size() - 1; ++i) {
        size_t minIdx = i;
        for (size_t j = i + 1; j < arr.size(); ++j) {
            if (arr[j] < arr[minIdx]) minIdx = j;
        }
        if (minIdx != i) swap(arr[i], arr[minIdx]);
    }
    return {arr, true};
}

