        private static Extents3d CalculateTotalBounds(List<EntityGeometry> entities)
        {
            var bounds = new Extents3d();
            foreach (var entity in entities)
            {
                if (entity != null)
                {
                    try
                    {
                        bounds.Add(entity.GetBounds());
                    }
                    catch { }
                }
            }
            return bounds;
