        private static double CalculateScaling(Extents3d bounds, int width, int height)
        {
            double scaleX = width / bounds.Size.X;
            double scaleY = height / bounds.Size.Y;
            return Math.Min(scaleX, scaleY) * 0.9; // 90% scale to add margin
        }

        private static Point3d CalculateOffset(Extents3d bounds, double scale, int width, int height)
        {
            return new Point3d(
                (width / 2) - (bounds.Center.X * scale),
                (height / 2) + (bounds.Center.Y * scale), // Y is inverted in bitmap
                0);
        }

        private static void DrawEntity(Graphics graphics, EntityGeometry entity, double scale, Point3d offset)
